// Audit 12daf8060 (DecimatorSamplingLib): a sealed Decimator round has T = N + M slots, N burned
// entries plus M jackpot-generated ones (ids N+1..N+M). Exactly S = min(1000, ceil(T/2)) slots
// survive: [0, T) splits into S floor-rounded strata, each stratum picks one position, and one
// common rotation shifts them all, so every slot survives with probability S/T and the whole set
// replays from (word, level, T). Unsampled entries are never visited and emit nothing. Mirrors the
// Lens `decSurvivorAt` and the audit's DecimatorSampleReference test oracle.
import { AbiCoder, id, keccak256 } from '../vendor/ethers-app.mjs';

const SAMPLE_TAG = id('decimator.battle.sample.v1');
const coder = AbiCoder.defaultAbiCoder();
const hash = (types, values) => BigInt(keccak256(coder.encode(types, values)));

/** S = min(1000, ceil(T / 2)): how many of `fieldEntries` slots survive. */
export function decimatorSurvivorCount(fieldEntries) {
  const count = (BigInt(fieldEntries) + 1n) / 2n;
  return count > 1000n ? 1000n : count;
}

/** The common rotation, H(SAMPLE_TAG, word, lvl) % T. */
export function decimatorSurvivorRotation(word, level, fieldEntries) {
  return hash(['bytes32', 'uint256', 'uint24'], [SAMPLE_TAG, BigInt(word), Number(level)]) % BigInt(fieldEntries);
}

/** The entry id stratum `stratum` keeps (Lens decSurvivorAt). */
export function decimatorSurvivorAt(word, level, fieldEntries, stratum) {
  const total = BigInt(fieldEntries); const count = decimatorSurvivorCount(total); const i = BigInt(stratum);
  if (total <= 0n || i < 0n || i >= count) throw new RangeError('Stratum outside the Decimator field.');
  const lo = (i * total) / count;
  const hi = ((i + 1n) * total) / count;
  const pos = lo + hash(['bytes32', 'uint256', 'uint24', 'uint256'], [SAMPLE_TAG, BigInt(word), Number(level), i]) % (hi - lo);
  return (pos + decimatorSurvivorRotation(word, level, total)) % total + 1n;
}

/** True when entry `entryId` (1..T) is one of the round's sampled survivors: one hash, no scan. */
export function decimatorSurvives(word, level, fieldEntries, entryId) {
  const total = BigInt(fieldEntries); const entry = BigInt(entryId);
  if (total <= 0n || entry < 1n || entry > total) return false;
  const pos = (entry - 1n + total - decimatorSurvivorRotation(word, level, total)) % total;
  // The unique stratum containing that unrotated position.
  const stratum = ((pos + 1n) * decimatorSurvivorCount(total) - 1n) / total;
  return decimatorSurvivorAt(word, level, total, stratum) === entry;
}
